suppressMessages({library(ggplot2); library(patchwork); library(strucchange)})
PROJ <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), "../..")) else getwd()
})
WS <- file.path(PROJ,"data_workspace_2026-07"); M <- file.path(WS,"allparty_review/marss")

net  <- read.csv(file.path(M,"aggregate_volatility_index.csv"))[,c("year","v","lo","hi")]   # GE + polls
comb <- read.csv(file.path(M,"volatility_index_pca_input.csv"))
cc   <- comb[!is.na(comb$v), c("year","v","lo","hi")]
sw   <- read.csv(file.path(WS,"switching_series","switching_recall_1979_2024.csv"))
z<-1.96; p<-sw$switching_rate/100; n<-sw$n; den<-1+z^2/n
sw$lo <- 100*(p+z^2/(2*n)-z*sqrt(p*(1-p)/n+z^2/(4*n^2)))/den
sw$hi <- 100*(p+z^2/(2*n)+z*sqrt(p*(1-p)/n+z^2/(4*n^2)))/den

# ===== STRUCTURAL-BREAK TEST — on the OBSERVED (un-smoothed) electoral-volatility index =====
# The MARSS latent is near-deterministic (rho~0.94) so a break test on it is invalid (F explodes).
# Test instead on the observed annual indicators the MARSS fuses, standardized and averaged:
#   GE Pedersen (election years) + poll volatility (annual). Real year-to-year noise -> valid test.
ge <- read.csv(file.path(M,"marss_ge_pedersen.csv"))
pv <- read.csv(file.path(M,"marss_poll_volatility.csv"))
YRS <- 1979:2026
zof <- function(vals, years){ z<-setNames(rep(NA_real_,length(YRS)),YRS); z[as.character(years)]<-as.numeric(scale(vals)); z }
obs <- data.frame(year=YRS, v=rowMeans(cbind(zof(ge$pedersen_ge,ge$year), zof(pv$poll_volatility,pv$year)), na.rm=TRUE))
obs <- obs[is.finite(obs$v), ]
d  <- obs
fs <- Fstats(v ~ year, data=d, from=0.15)
supF <- max(fs$Fstats); pval <- sctest(fs)$p.value
bpf   <- breakpoints(v ~ year, data=d, h=0.15)            # full RSS/BIC object
nbic  <- if (all(is.na(bpf$breakpoints))) 0L else length(bpf$breakpoints)
ci    <- confint(bpf, breaks=1, level=0.90)$confint       # best SINGLE break + 90% CI
brkyr <- d$year[ci[1,2]]
ci_lo <- ifelse(is.na(ci[1,1]), min(d$year), d$year[ci[1,1]])
ci_hi <- ifelse(is.na(ci[1,3]), max(d$year), d$year[ci[1,3]])
# AR(1)-null guard (a smoothed latent is persistent -> inflates sup-F; test against AR(1))
ar1 <- ar(d$v, order.max=1, aic=FALSE, method="yule-walker"); rho <- ar1$ar; sdi <- sqrt(ar1$var.pred)
set.seed(1)
nullF <- replicate(3000, { x <- as.numeric(arima.sim(n=nrow(d), list(ar=max(min(rho,.99),-.99)), sd=sdi))
  max(Fstats(x ~ d$year, from=0.15)$Fstats) })
p_ar1 <- mean(nullF >= supF)
cat(sprintf("ELECTORAL-VOL break: %d  (90%% CI %d-%d)  sup-F=%.1f  asym p=%.4f  AR(1)-null p=%.3f  [rho=%.2f]\n",
            brkyr, ci_lo, ci_hi, supF, pval, p_ar1, rho))

BRKlab <- sprintf("Chow / sup-F break: %d\nsup-F=%.1f, p=%s\n90%% CI %d–%d", brkyr, supF,
                  ifelse(pval<0.001,"<.001",sprintf("%.3f",pval)), ci_lo, ci_hi)

YL <- c(min(c(net$lo,cc$lo)), max(c(net$hi,cc$hi)))
XB <- scale_x_continuous(breaks=seq(1980,2020,10), limits=c(1979,2026))
# ⏸ PRINT-RELATIVE TYPE REVERTED 17 Aug. PJ: "feel this is a mess - maybe live with what I have
