base <- theme_minimal(base_size=12) + theme(legend.position="none",
  plot.subtitle=element_text(face="italic",hjust=0,colour="grey30",size=9),
  plot.tag=element_text(face="bold", size=11),
  panel.grid.minor=element_blank(), axis.title=element_text(size=10,colour="grey15"),
  plot.title=element_text(face="bold",size=14.5), plot.caption=element_text(size=7,colour="grey40",hjust=0))
vpanel <- function(df,lab){ ggplot(df,aes(year,v))+geom_hline(yintercept=0,colour="grey85")+
  geom_ribbon(aes(ymin=lo,ymax=hi),fill="grey70",alpha=.30)+geom_line(colour="#000000",linewidth=1.1)+
  coord_cartesian(ylim=YL)+XB+labs(subtitle=lab,x=NULL,y="z")+base+theme(axis.text.x=element_blank()) }

# ⭐ PANEL 1 REPLACED 17 Aug, PJ: "good to start with the basic index as this is where everyone
